var scene=UnityEngine.SceneManagement.SceneManager.CreateScene("Isolated motor checks",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics2D));var physics=scene.GetPhysicsScene2D();
var host=new UnityEngine.GameObject("Isolated motor rig");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(host,scene);host.SetActive(false);
var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Character.prefab");var clone=UnityEngine.Object.Instantiate(prefab,host.transform);
foreach(var m in clone.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true))if(!(m is Character.Control.TargetMovement)&&!(m is Character.Control.ArmsSimulation))UnityEngine.Object.DestroyImmediate(m);
host.SetActive(true);var arms=clone.GetComponentInChildren<Character.Control.ArmsSimulation>();var input=clone.GetComponentInChildren<Character.Control.TargetMovement>();input.enabled=false;input.ResetTarget();
var body=clone.transform.Find("Cauldron").GetComponent<UnityEngine.Rigidbody2D>();body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;
foreach(var rb in clone.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.gravityScale=0;
void Tick(int n){for(int i=0;i<n;i++){arms.SendMessage("FixedUpdate");physics.Simulate(.02f);}}
try{
 var origin=(UnityEngine.Vector2)body.position;arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,-.95f));Tick(220);
 var shape=clone.transform.Find("Hammer/Shape").GetComponent<UnityEngine.PolygonCollider2D>();var floor=new UnityEngine.GameObject("Arm-limited support floor");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(floor,scene);floor.AddComponent<UnityEngine.BoxCollider2D>().size=new UnityEngine.Vector2(12,.2f);floor.transform.position=new UnityEngine.Vector3(body.position.x,shape.bounds.min.y-.11f,0);
 body.gravityScale=1;body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeRotation;float startY=body.position.y;arms.ReceiveTarget(origin+new UnityEngine.Vector2(0,-2.8f));UnityEngine.Physics2D.SyncTransforms();float worst=0;
 for(int k=0;k<40;k++){Tick(1);var axis=(UnityEngine.Vector2)clone.transform.Find("Hammer").right;var tip=(UnityEngine.Vector2)arms.HammerTip.position;
  for(int i=0;i<2;i++){UnityEngine.Vector2 shoulder=body.transform.position+body.transform.up*.66f+body.transform.right*(i==0?-.19f:.19f);float distance=UnityEngine.Vector2.Distance(shoulder,tip-axis*((i==0?228:200)*2.15f/230));worst=UnityEngine.Mathf.Max(worst,distance);}}
 float rise=body.position.y-startY;string log="Arm-limited gravity support: body rise="+rise+" max shoulder-grip="+worst+" natural arm=.98";
 System.IO.File.WriteAllText("scripts/paddle-arm-limit-20261111/support.txt",log);UnityEngine.Debug.Log(log);
 if(rise<.05f||worst>.985f)throw new System.Exception("Support/reach regression");
}finally{UnityEngine.Object.DestroyImmediate(host);UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);}
